-- Create "audit_logs" table
CREATE TABLE "audit_logs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "ts" timestamptz NOT NULL, "org_id" bigint NULL, "actor_id" bigint NULL, "actor_email" character varying NOT NULL DEFAULT '', "action" character varying NOT NULL, "resource_type" character varying NOT NULL DEFAULT '', "resource_id" character varying NOT NULL DEFAULT '', "phase" character varying NOT NULL DEFAULT 'result', "outcome" character varying NOT NULL DEFAULT '', "ip" character varying NOT NULL DEFAULT '', "user_agent" character varying NOT NULL DEFAULT '', "request_id" character varying NOT NULL DEFAULT '', "trace_id" character varying NOT NULL DEFAULT '', "detail" jsonb NULL, PRIMARY KEY ("id"));
-- Create index "auditlog_actor_id_ts" to table: "audit_logs"
CREATE INDEX "auditlog_actor_id_ts" ON "audit_logs" ("actor_id", "ts");
-- Create index "auditlog_trace_id" to table: "audit_logs"
CREATE INDEX "auditlog_trace_id" ON "audit_logs" ("trace_id");
-- Create index "auditlog_ts" to table: "audit_logs"
CREATE INDEX "auditlog_ts" ON "audit_logs" ("ts");
-- Create "organizations" table
CREATE TABLE "organizations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "slug" character varying NOT NULL, PRIMARY KEY ("id"));
-- Create index "organizations_slug_key" to table: "organizations"
CREATE UNIQUE INDEX "organizations_slug_key" ON "organizations" ("slug");
-- Create "tools" table
CREATE TABLE "tools" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "key" character varying NOT NULL, "name" character varying NOT NULL, "source" character varying NOT NULL DEFAULT 'mcp', "enabled" boolean NOT NULL DEFAULT false, "exec_mode" character varying NOT NULL DEFAULT 'require_approval', PRIMARY KEY ("id"));
-- Create index "tools_key_key" to table: "tools"
CREATE UNIQUE INDEX "tools_key_key" ON "tools" ("key");
-- Create "departments" table
CREATE TABLE "departments" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "external_id" character varying NULL, "parent_id" bigint NULL, "org_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "departments_departments_children" FOREIGN KEY ("parent_id") REFERENCES "departments" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "departments_organizations_departments" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "department_org_id_parent_id_name" to table: "departments"
CREATE UNIQUE INDEX "department_org_id_parent_id_name" ON "departments" ("org_id", "parent_id", "name");
-- Create "roles" table
CREATE TABLE "roles" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "key" character varying NOT NULL, "name" character varying NOT NULL, "permissions" jsonb NOT NULL, "builtin" boolean NOT NULL DEFAULT false, PRIMARY KEY ("id"));
-- Create index "roles_key_key" to table: "roles"
CREATE UNIQUE INDEX "roles_key_key" ON "roles" ("key");
-- Create "users" table
CREATE TABLE "users" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "email" character varying NOT NULL, "display_name" character varying NOT NULL DEFAULT '', "password_hash" character varying NULL, "status" character varying NOT NULL DEFAULT 'active', "is_super_admin" boolean NOT NULL DEFAULT false, "last_login_at" timestamptz NULL, "org_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "users_organizations_users" FOREIGN KEY ("org_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "users_email_key" to table: "users"
CREATE UNIQUE INDEX "users_email_key" ON "users" ("email");
-- Create "memberships" table
CREATE TABLE "memberships" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "is_primary" boolean NOT NULL DEFAULT false, "department_id" bigint NULL, "role_id" bigint NOT NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "memberships_departments_memberships" FOREIGN KEY ("department_id") REFERENCES "departments" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "memberships_roles_memberships" FOREIGN KEY ("role_id") REFERENCES "roles" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "memberships_users_memberships" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "membership_user_id_role_id_department_id" to table: "memberships"
CREATE UNIQUE INDEX "membership_user_id_role_id_department_id" ON "memberships" ("user_id", "role_id", "department_id");
